#define main legacy_main
#include "../nw-cuda/nw.cu"
#undef main
#include <vector>
#include <string>
#include <algorithm>
struct Fixture{int dim,p;std::vector<int>s1,s2,ref,initial,gold;int *di,*dr;Fixture(int f){dim=f==1?64:f==2?96:32;p=f==1?10:f==2?3:2;int cols=dim+1;s1.resize(dim);s2.resize(dim);if(f==1){srand(7);for(int&i:s1)i=rand()%10+1;for(int&i:s2)i=rand()%10+1;}else if(f==2)for(int i=0;i<dim;i++){s1[i]=(7*i+3)%24;s2[i]=(5*i+11)%24;}ref.assign(cols*cols,0);initial=ref;for(int i=1;i<=dim;i++){initial[i*cols]=-i*p;initial[i]=-i*p;for(int j=1;j<=dim;j++)ref[i*cols+j]=blosum62[s1[i-1]][s2[j-1]];}gold=initial;nw_host(gold.data(),ref.data(),cols,p);std::vector<long long>ind(initial.begin(),initial.end());for(int i=1;i<=dim;i++)for(int j=1;j<=dim;j++){int k=i*cols+j;ind[k]=std::max({ind[k-cols-1]+ref[k],ind[k-1]-p,ind[k-cols]-p});}for(size_t i=0;i<gold.size();i++)if(gold[i]!=ind[i])exit(5);if(f==3)for(int i=0;i<=dim;i++)for(int j=0;j<=dim;j++)if(gold[i*cols+j]!=4*std::min(i,j)-p*abs(i-j))exit(6);cudaMalloc(&di,initial.size()*4);cudaMalloc(&dr,ref.size()*4);cudaMemcpy(di,initial.data(),initial.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dr,ref.data(),ref.size()*4,cudaMemcpyHostToDevice);}
void launch(){int width=dim/16;for(int blk=1;blk<=width;blk++)kernel1<<<blk,16>>>(di,dr,0,0,dim+1,blk,p);for(int blk=width-1;blk>=1;blk--)kernel2<<<blk,16>>>(di,dr,width,0,0,dim+1,blk,p);}
bool trace(const std::vector<int>&g){int cols=dim+1,i=dim,j=dim,score=0,c1=0,c2=0;while(i||j){int v=g[i*cols+j];if(i&&j&&v==g[(i-1)*cols+j-1]+blosum62[s1[i-1]][s2[j-1]]){score+=blosum62[s1[i-1]][s2[j-1]];i--;j--;c1++;c2++;}else if(j&&v==g[i*cols+j-1]-p){score-=p;j--;c2++;}else if(i&&v==g[(i-1)*cols+j]-p){score-=p;i--;c1++;}else return false;}return score==g.back()&&c1==dim&&c2==dim;}};
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):20;std::vector<Fixture>fs;for(int f=1;f<=3;f++)fs.emplace_back(f);std::vector<int>prefix;for(auto&f:fs){for(auto*a:{&f.ref,&f.initial,&f.s1,&f.s2})prefix.insert(prefix.end(),a->begin(),a->end());prefix.push_back(f.dim);prefix.push_back(f.p);f.launch();}cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){for(auto&f:fs)cudaMemcpy(f.di,f.initial.data(),f.initial.size()*4,cudaMemcpyHostToDevice);cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int rep=0;rep<repeat;rep++)for(auto&f:fs)f.launch();cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/repeat;bool ok=cudaGetLastError()==cudaSuccess;std::vector<int>got;for(auto&f:fs){std::vector<int>g(f.initial.size());cudaMemcpy(g.data(),f.di,g.size()*4,cudaMemcpyDeviceToHost);ok&=g==f.gold&&f.trace(g);got.insert(got.end(),g.begin(),g.end());}auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"three_complete_global_alignment_matrices_no_H2D_inside\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),repeat,path.c_str(),art.size());if(!ok)return 2;}for(auto&f:fs){cudaFree(f.di);cudaFree(f.dr);}}
